<?php
declare(strict_types=1);
use App\Domain\{Contributors, ProgramHtml};
$categoryNames = ['code' => 'Cod', 'documentation' => 'Documentație', 'research' => 'Cercetare', 'design' => 'Design', 'testing' => 'Testare', 'translation' => 'Traducere', 'support' => 'Suport', 'community' => 'Comunitate'];
?>
<?php if ($screen === 'contributors'): ?>
<form method="get" class="program-filters" role="search"><label>Nume sau pseudonim<input class="form-control" name="q" maxlength="100" value="<?=e(is_string($_GET['q'] ?? null) ? $_GET['q'] : '')?>"></label><label>Categorie<select class="form-select" name="category" aria-label="Categoria contribuției"><option value="">Toate</option><?php foreach ($categoryNames as $key => $name): ?><option value="<?=e($key)?>" <?=($_GET['category'] ?? '') === $key ? 'selected' : ''?>><?=e($name)?></option><?php endforeach ?></select></label><button class="btn btn-outline-primary" type="submit">Caută</button></form>
<div class="program-intro"><p>Cod, cercetare, documentație și idei care fac informația despre alimente mai accesibilă. Aici recunoaștem contribuțiile oamenilor, cu acordul lor.</p><a class="btn btn-primary" href="/contribuitori/cont">Adaugă contribuția ta <?=icon('arrow')?></a></div>
<?php if (!$model['items']): ?><section class="panel"><h2>Construim împreună</h2><p>Profilurile apar după confirmarea persoanei și verificarea contribuției. Poți participa prin cod, documentație, cercetare sau testare.</p><a href="https://github.com/web3metatrade/openaliment" rel="noopener noreferrer">Proiectul pe GitHub</a></section><?php endif ?>
<div class="program-grid"><?php foreach ($model['items'] as $item): $p = $item['profile']; ?><article class="panel program-card"><?php if ($p['asset_id']): ?><img class="program-avatar" src="/program/imagini/<?=e($p['asset_id'])?>" width="80" height="80" alt=""><?php endif ?><h2><a href="/contribuitori/<?=e($item['id'])?>"><?=e($p['name'])?></a></h2><p><?=e(mb_strimwidth($p['summary'], 0, 260, '…'))?></p><p class="small muted"><?=e(implode(' · ', array_map(static fn(string $c): string => $categoryNames[$c], $p['categories'])))?></p></article><?php endforeach ?></div><?php $page($model); ?>
<?php elseif ($screen === 'contributor-public'): $p = $model['profile']; ?>
<article class="panel program-reading"><?php if ($p['asset_id']): ?><img class="program-avatar" src="/program/imagini/<?=e($p['asset_id'])?>" width="96" height="96" alt=""><?php endif ?><p><?=e($p['summary'])?></p><p class="muted"><?=e(implode(' · ', array_map(static fn(string $c): string => $categoryNames[$c], $p['categories'])))?></p><?php foreach ($p['links'] as $link): ?><p><a href="<?=e($link)?>" rel="noopener noreferrer"><?=e($link)?></a></p><?php endforeach ?></article><a href="/contribuitori">← Toți contribuitorii</a>
<?php else: ?>
<?php if (isset($model['items'])): foreach ($model['items'] as $item): ?><a class="list-row" href="/contribuitori/cont/<?=e($item['id'])?>"><strong><?=e($item['profile']['name'])?></strong><span><?=e(ProgramHtml::state($item['state']))?> <?=icon('arrow')?></span></a><?php endforeach; endif ?>
<?php $editing = isset($model['id']); $p = $model['profile'] ?? ['name' => $programUser['display_name'], 'summary' => '', 'categories' => [], 'links' => [], 'asset_id' => null]; ?>
<section class="panel program-reading"><h2><?=$editing ? 'Editează profilul' : 'Prezintă contribuția ta'?></h2><p class="muted">Poți folosi numele tău sau un pseudonim. Modificările sunt verificate înainte de publicare.</p>
<?php $form($editing ? 'contributor_save' : 'contributor_create', $model['id'] ?? '', $editing ? ['expected_revision' => $model['revision']] : []); $field('name', 'Nume sau pseudonim', $p['name']); if (!$editing) { $field('slug', 'Adresă scurtă a profilului', '', 'text'); } $area('summary', 'Cum contribui la OpenAliment', $p['summary']); ?>
<fieldset><legend class="h6">Tipul contribuției</legend><div class="program-checks"><?php foreach ($categoryNames as $key => $label): ?><label class="check-label"><input type="checkbox" name="categories[]" value="<?=e($key)?>" <?=in_array($key, $p['categories'], true) ? 'checked' : ''?>> <?=e($label)?></label><?php endforeach ?></div></fieldset>
<?php $area('links', 'Legături publice, câte una pe rând', implode("\n", $p['links']), 3); echo '<input type="hidden" name="asset_id" value="' . e($p['asset_id'] ?? '') . '">'; $check('consent', 'Sunt de acord cu publicarea acestor informații în lista contribuitorilor.'); $submit('Salvează profilul'); ?>
<?php if ($editing): ?><p class="small">Stare: <?=e(ProgramHtml::state($model['state']))?> · Revizia <?=e((string) $model['revision'])?></p><?php $form('contributor_submit', $model['id'], ['expected_revision' => $model['revision']]); $check('consent', 'Confirm publicarea reviziei curente.'); $submit('Trimite pentru publicare'); $form('contributor_withdraw', $model['id']); $submit('Retrage publicarea', true); endif ?>
</section>
<section class="panel program-reading"><h2>Fotografie opțională</h2><p class="muted">PNG, JPEG sau WebP, cel mult 2 MB. Folosește numai o imagine pe care ai dreptul să o publici.</p><div data-program-upload="avatar"><label>Alege imaginea<input class="form-control" type="file" accept="image/png,image/jpeg,image/webp"></label><label class="check-label"><input type="checkbox" data-upload-rights> Confirm dreptul de publicare.</label><button class="btn btn-outline-primary" type="button" data-upload-button>Încarcă fotografia</button><p role="status" data-upload-status></p></div></section>
<?php endif ?>
